	edges = make([][2]int, m)
	for i := 0; i < m; i++ {
		var a, b int
		fmt.Fscan(in, &a, &b)
		edges[i] = [2]int{a, b}
	}

	used := make([]bool, 22)
	assignment := make([]int, n+1)

	maxDominoes = 0
	backtrack(0, 0, used, assignment)
	fmt.Println(maxDominoes)
}

func backtrack(edgeIdx, count int, used []bool, assignment []int) {
	if count > maxDominoes {
		maxDominoes = count
	}
	if edgeIdx >= m {
		return
	}

	// Skip this edge
	backtrack(edgeIdx+1, count, used, assignment)

	// Try placing a domino on this edge
	a, b := edges[edgeIdx][0], edges[edgeIdx][1]
	for x := 1; x <= 6; x++ {
		for y := x; y <= 6; y++ {
			dominoID := x*6 + y - x*(x-1)/2
			if used[dominoID] {
				continue
			}

			// Check if we can assign x to a and y to b
			if canAssign(a, x, assignment) && canAssign(b, y, assignment) {
				used[dominoID] = true
				assignment[a] = x
				assignment[b] = y
				backtrack(edgeIdx+1, count+1, used, assignment)
				used[dominoID] = false
				assignment[a] = 0
				assignment[b] = 0
			}

			// Check if we can assign y to a and x to b (if x != y)
			if x != y {
				if canAssign(a, y, assignment) && canAssign(b, x, assignment) {
					used[dominoID] = true
					assignment[a] = y
					assignment[b] = x
					backtrack(edgeIdx+1, count+1, used, assignment)
					used[dominoID] = false
					assignment[a] = 0
					assignment[b] = 0
				}
			}
		}
	}
}

func canAssign(vertex, value int, assignment []int) bool {
	if assignment[vertex] == 0 {
		return true
	}
	return assignment[vertex] == value
