package main

import (
	"bufio"
	"fmt"
	"os"
)

var reader = bufio.NewReader(os.Stdin)
var writer = bufio.NewWriter(os.Stdout)

func main() {
	defer writer.Flush()

	var n, m int
	fmt.Fscan(reader, &n, &m)

	edges := make([][2]int, m)
	for i := 0; i < m; i++ {
		var a, b int
		fmt.Fscan(reader, &a, &b)
		edges[i] = [2]int{a - 1, b - 1}
	}

	maxDominoes := 0

	// Try all possible assignments of numbers to vertices (each vertex gets a number from 0 to 6)
	// There are 7^n possible assignments
	for mask := 0; mask < (1 << (n * 3)); mask++ {
		// Extract the number assigned to each vertex
		vertexNum := make([]int, n)
		for i := 0; i < n; i++ {
			vertexNum[i] = (mask >> (i * 3)) & 7
		}

		// For each edge, determine the domino type
		used := make(map[[2]int]bool)
		count := 0

		valid := true
		for _, e := range edges {
			a, b := e[0], e[1]
			numA := vertexNum[a]
			numB := vertexNum[b]

			// Create a sorted pair to represent the domino type
			var domino [2]int
			if numA <= numB {
				domino = [2]int{numA, numB}
			} else {
				domino = [2]int{numB, numA}
			}

			if !used[domino] {
				used[domino] = true
				count++
			}
		}

		if count > maxDominoes {
			maxDominoes = count
		}
	}

	fmt.Fprintln(writer, maxDominoes)
}
