var n, m int
var edges [][2]int
var used [22]bool
var best int

func main() {
	in := bufio.NewReader(os.Stdin)
	fmt.Fscan(in, &n, &m)
	edges = make([][2]int, m)
	for i := 0; i < m; i++ {
		var a, b int
		fmt.Fscan(in, &a, &b)
		edges[i] = [2]int{a, b}
	}
	best = 0
	// Try all assignments of numbers 1..6 to vertices
	assign := make([]int, n+1) // assign[v] = number assigned to vertex v
	dfs(1, assign)
	fmt.Println(best)
}

func dfs(v int, assign []int) {
	if v > n {
		// Count how many dominoes can be placed
		used = [22]bool{}
		count := 0
		for _, e := range edges {
			a, b := e[0], e[1]
			x, y := assign[a], assign[b]
			if x > y {
				x, y = y, x
			}
			idx := dominoIndex(x, y)
			if !used[idx] {
				used[idx] = true
				count++
			}
		}
		if count > best {
			best = count
		}
		return
	}
	for num := 1; num <= 6; num++ {
		assign[v] = num
		dfs(v+1, assign)
	}
}

func dominoIndex(a, b int) int {
	// a <= b, both in 1..6
	// index = sum_{i=1}^{a-1} (6 - i + 1) + (b - a)
	// = sum_{i=1}^{a-1} (7 - i) + (b - a)
	idx := 0
	for i := 1; i < a; i++ {
		idx += 7 - i
	}
	idx += b - a
	return idx
}
