```go
package main

import (
	"fmt"
)

func main() {
	var n, m int
	fmt.Scan(&n, &m)
	edges := make([][2]int, m)
	for i := 0; i < m; i++ {
		var a, b int
		fmt.Scan(&a, &b)
		edges[i] = [2]int{a - 1, b - 1} // convert to 0-based
	}

	maxDominoes := 0

	// Iterate over all possible assignments of values (0-6) to each vertex
	// Since n can be up to 7, and each vertex has 7 choices, total is 7^7 = 823543
	for mask := 0; mask < (1 << (3 * n)); mask++ {
		// Extract the values for each vertex from the mask
		values := make([]int, n)
		valid := true
		for i := 0; i < n; i++ {
			shift := 3 * i
			val := (mask >> shift) & 0x7
			if val > 6 {
				valid = false
				break
			}
			values[i] = val
		}
		if !valid {
			continue
		}

		// Collect all dominoes for this assignment
		seen := make(map[[2]int]bool)
		for _, e := range edges {
			u := e[0]
			v := e[1]
			a := values[u]
			b := values[v]
			if a > b {
				a, b = b, a
			}
			seen[[2]int{a, b}] = true
		}

		if len(seen) > maxDominoes {
			maxDominoes = len(seen)
		}
	}

	fmt.Println(maxDominoes)
}
