		// Each vertex uses 3 bits, so values can be 0-7, but we need 1-6
		// So we'll use 3 bits per vertex and map 0-5 to 1-6, and 6-7 are invalid
		valid := true
		vertexValues := make([]int, n+1) // 1-based indexing
		for v := 1; v <= n; v++ {
